// Twitter Content Strategy Generator
const tweetTypes = [
  'industry insight thread',
  'quick tip tweet',
  'trending topic commentary',
  'educational thread',
  'behind-the-scenes',
  'question to community',
  'resource sharing',
  'personal story',
  'company update',
  'tech news reaction'
];

const industries = [
  'artificial intelligence',
  'software development',
  'startup ecosystem',
  'remote work culture',
  'digital marketing',
  'productivity tools',
  'tech entrepreneurship',
  'automation trends',
  'business strategy',
  'innovation insights'
];

const threadStructures = [
  'problem-solution-results',
  'listicle with explanations',
  'story with lessons learned',
  'comparison and analysis',
  'step-by-step tutorial',
  'myth-busting facts',
  'prediction and reasoning',
  'personal experience sharing'
];

const currentHour = new Date().getHours();
let contentType;

// Time-based content strategy
if (currentHour < 10) {
  contentType = 'motivational insight';
} else if (currentHour < 14) {
  contentType = 'educational content';
} else if (currentHour < 18) {
  contentType = 'industry news reaction';
} else {
  contentType = 'community engagement';
}

const selectedType = tweetTypes[Math.floor(Math.random() * tweetTypes.length)];
const selectedIndustry = industries[Math.floor(Math.random() * industries.length)];
const selectedStructure = threadStructures[Math.floor(Math.random() * threadStructures.length)];

const prompt = `Create engaging Twitter content about ${selectedIndustry}.

Content Type: ${selectedType}
Content Focus: ${contentType}
Thread Structure: ${selectedStructure}

Requirements:
1. If single tweet: max 280 characters, punchy and engaging
2. If thread: 3-7 tweets, numbered, each under 280 characters
3. Include relevant emojis and hashtags
4. Add a compelling hook in the first tweet
5. End with a call-to-action or question
6. Make it valuable and shareable
7. Use conversational tone

Target audience: Tech entrepreneurs, developers, and business professionals.

Format your response as:
[THREAD] or [SINGLE TWEET]
Tweet 1: [content]
Tweet 2: [content] (if thread)
...
Hashtags: [relevant hashtags]
Best posting time: [suggestion]`;

return [{
  json: {
    selectedType,
    selectedIndustry,
    selectedStructure,
    contentType,
    claude_prompt: prompt,
    timestamp: new Date().toISOString(),
    currentHour
  }
}];

// Parse Claude's Twitter response
const response = $input.first().json.content;
const strategyData = $('Twitter Strategy Generator').first().json;

// Determine if it's a thread or single tweet
const isThread = response.includes('[THREAD]');
const isSingleTweet = response.includes('[SINGLE TWEET]');

// Split response into sections
const lines = response.split('\n').filter(line => line.trim());

let tweets = [];
let hashtags = '';
let bestTime = '';

// Parse tweets
lines.forEach(line => {
  if (line.match(/^Tweet \d+:/)) {
    const tweetContent = line.replace(/^Tweet \d+:\s*/, '').trim();
    tweets.push({
      content: tweetContent,
      length: tweetContent.length,
      valid: tweetContent.length <= 280
    });
  } else if (line.toLowerCase().includes('hashtags:')) {
    hashtags = line.replace(/.*hashtags:\s*/i, '').trim();
  } else if (line.toLowerCase().includes('best posting time:')) {
    bestTime = line.replace(/.*best posting time:\s*/i, '').trim();
  }
});

// If no structured tweets found, try to extract from response
if (tweets.length === 0) {
  const tweetMatches = response.match(/\d+\/?\d*[.)]\s*([^\n]+)/g);
  if (tweetMatches) {
    tweets = tweetMatches.map((match, index) => {
      const content = match.replace(/^\d+\/?\d*[.)]\s*/, '').trim();
      return {
        content,
        length: content.length,
        valid: content.length <= 280
      };
    });
  }
}

// Extract hashtags if not found
if (!hashtags) {
  const hashtagMatch = response.match(/#[\w]+/g);
  if (hashtagMatch) {
    hashtags = hashtagMatch.join(' ');
  }
}

const twitterContent = {
  id: `twitter_${Date.now()}`,
  type: isThread ? 'thread' : 'single',
  industry: strategyData.selectedIndustry,
  contentType: strategyData.contentType,
  structure: strategyData.selectedStructure,
  tweets: tweets,
  hashtags: hashtags,
  suggestedTime: bestTime || `${strategyData.currentHour + 1}:00`,
  totalCharacters: tweets.reduce((sum, tweet) => sum + tweet.length, 0),
  validTweets: tweets.filter(tweet => tweet.valid).length,
  invalidTweets: tweets.filter(tweet => !tweet.valid).length,
  createdAt: new Date().toISOString(),
  status: 'draft',
  platform: 'twitter',
  readyToPost: tweets.length > 0 && tweets.every(tweet => tweet.valid)
};

return [{
  json: twitterContent
}];

// Enhance content with trend analysis
const twitterContent = $('Twitter Content Parser').first().json;
const trendData = $input.first().json;

// Analyze trending topics and engagement
let trendingHashtags = [];
let avgEngagement = 0;
let trendInsights = 'No trend data available';

if (trendData.data && trendData.data.length > 0) {
  // Extract popular hashtags from trending tweets
  const allHashtags = [];
  let totalLikes = 0;
  let totalRetweets = 0;

  trendData.data.forEach(tweet => {
    if (tweet.public_metrics) {
      totalLikes += tweet.public_metrics.like_count;
      totalRetweets += tweet.public_metrics.retweet_count;
    }

    // Extract hashtags
    const hashtags = tweet.text.match(/#[\w]+/g) || [];
    allHashtags.push(...hashtags);
  });

  // Count hashtag frequency
  const hashtagCounts = {};
  allHashtags.forEach(tag => {
    hashtagCounts[tag] = (hashtagCounts[tag] || 0) + 1;
  });

  // Get top trending hashtags
  trendingHashtags = Object.entries(hashtagCounts)
    .sort(([,a], [,b]) => b - a)
    .slice(0, 5)
    .map(([tag]) => tag);

  avgEngagement = Math.round((totalLikes + totalRetweets) / trendData.data.length);

  trendInsights = `Current trends show ${avgEngagement} avg engagement. Top hashtags: ${trendingHashtags.slice(0, 3).join(', ')}`;
}

// Merge trending hashtags with content hashtags
const existingHashtags = twitterContent.hashtags.split(' ').filter(tag => tag.trim());
const combinedHashtags = [...new Set([...existingHashtags, ...trendingHashtags.slice(0, 2)])].join(' ');

// Enhanced content with trends
const enhancedContent = {
  ...twitterContent,
  hashtags: combinedHashtags,
  trendInsights: trendInsights,
  avgEngagement: avgEngagement,
  trendingHashtags: trendingHashtags,
  optimizedForTrends: true
};

return [{
  json: enhancedContent
}];

