// Prepare Twitter posting instructions
const content = $input.first().json;

// Create posting instructions for each tweet
const postingPlan = {
  platform: 'twitter',
  action: 'ready_to_schedule',
  threadId: content.id,
  type: content.type,
  totalTweets: content.tweets.length,
  tweets: content.tweets.map((tweet, index) => ({
    order: index + 1,
    content: tweet.content,
    length: tweet.length,
    isValid: tweet.valid,
    instructions: index === 0 
      ? 'Post as main tweet' 
      : `Reply to tweet ${index} immediately after posting`
  })),
  hashtags: content.hashtags,
  scheduledTime: content.suggestedTime,
  postingInstructions: [
    '1. Copy first tweet content',
    '2. Post on Twitter',
    '3. If thread: immediately reply with subsequent tweets',
    '4. Add hashtags to final tweet',
    '5. Monitor for engagement',
    '6. Respond to quality replies within 2 hours'
  ],
  engagementStrategy: {
    firstHour: 'Monitor and respond to all replies',
    ongoing: 'Like thoughtful responses, retweet quality reactions',
    metrics: 'Track likes, retweets, replies, and click-through rates'
  },
  trendOptimization: content.trendInsights
};

return [{
  json: postingPlan
}];
